insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('tlaquepaque-mexico', '10S', 'Tlaquepaque', 'Mexico', 'Jalisco ceramics, mariachi and birria', 'live', 'verified', 'kyoto', 'Jalisco (Puerto Vallarta & Guadalajara)', '{"culture","culinary"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":["One of the eight municipalities of the Guadalajara metropolitan area (2020 metro pop. ~5.27M) (Source: en.wikipedia.org, Accessed 2026-07-04)","Designated a Pueblo Mágico since October 2018 (Source: gob.mx/sectur, Accessed 2026-07-04)","With Tonalá, one of Mexico''s two main ceramics centers; ~2,000 artisans (Source: fernwayer.com, Accessed 2026-07-04)","El Parián is the iconic open-air mariachi cantina courtyard (Source: travelmexicosolo.com, Accessed 2026-07-04)","GDL (Guadalajara Intl) is ~11 mi / ~17 min from Tlaquepaque center (Source: rome2rio.com, Accessed 2026-07-04)"],"safety":{"emergency":"911","hospital":"Guadalajara-metro private hospitals (Hospital San Javier GDL, Puerta de Hierro; verify nearest to Tlaquepaque Centro); air-evac via GDL","advisory_level":"L3","book_enabled":true,"tourist_zone_carveout":"Guadalajara Metro (named)","air_access_verified":"GDL (Guadalajara Intl)","malaria":"none (inland highland)","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Year-round (event/holiday-led; inland metro)","shoulder":"Weekdays / low-event windows","green":"n/a (no coastal season; no hurricane exposure)","booking_lead":"2–6 weeks typical; 2–3 months around major GDL events","off_season_specials":"Weekday craft/culinary half-day paired with a Guadalajara city stay","event_peaks":"FIL Guadalajara book fair (late Nov/early Dec); Premio Nacional de la Cerámica (verify current-year dates)","campaign_start":"6–8 weeks ahead of target GDL events; always-on evergreen for day-trip/city-break audience"},"jewels":[{"name":"Calle Independencia (Andador Independencia)","si_tag":"Culture & Heritage","status":"future","hook":"Pedestrian gallery street — Talavera, blown glass, textiles, contemporary art","bookable_category":"tour","tier":"essential","source":"https://travelmexicosolo.com/tlaquepaque-jalisco-mexico-guide/ (Accessed 2026-07-04)","si":"culture","blurb":"Pedestrian gallery street — Talavera, blown glass, textiles, contemporary art","commission":"tour affiliate ~8–12% (guided version)","accessed":"2026-07-04"},{"name":"Museo Regional de la Cerámica / Premio Nacional de la Cerámica","si_tag":"Culture & Heritage","status":"future","hook":"National ceramics-prize museum in Centro Cultural El Refugio","bookable_category":"attraction","tier":"essential","source":"https://www.afar.com/magazine/in-guadalajara-young-designers-are-putting-a-modern-spin-on-traditional-ceramics (Accessed 2026-07-04)","si":"culture","blurb":"National ceramics-prize museum in Centro Cultural El Refugio","commission":"via tour package only (entry non-commissionable)","accessed":"2026-07-04"},{"name":"Tlaquepaque + Tonalá private pottery tour with clay workshop","si_tag":"Culture & Heritage","status":"future","hook":"Hands-on half-day across both craft towns","bookable_category":"tour","tier":"comfort","source":"https://www.pelago.com/en-US/activity/p4g83fk6p-tonala-tlaquepaque-tour-art-towns-pottery-experience-guadalajara/ (Accessed 2026-07-04)","si":"culture","blurb":"Hands-on half-day across both craft towns","commission":"tour affiliate ~8–12%","accessed":"2026-07-04"},{"name":"El Parián","si_tag":"Culinary / Nightlife","status":"future","hook":"Open-air colonial cantina — mariachi over birria and tequila, midday into night","bookable_category":"attraction","tier":"essential","source":"https://travelmexicosolo.com/tlaquepaque-jalisco-mexico-guide/ (Accessed 2026-07-04)","si":"Culinary / Nightlife","blurb":"Open-air colonial cantina — mariachi over birria and tequila, midday into night","commission":"via food/culture tour package (walk-in dining non-commissionable)","accessed":"2026-07-04"}],"faq":[{"q":"How do I stay in the safe zone?","a":"Fly into GDL — ~11 mi / ~17 min away — and stay within the Guadalajara metro / Tlaquepaque Centro. The Level 3 restrictions apply to rural southern-Jalisco highway corridors, not the metro; don''t self-drive into the Jalisco interior, and keep valuables discreet in the El Parián crowds.","source":"travel.state.gov / rome2rio.com, 2026-07-04","si_tag":"safety"},{"q":"Why is Tlaquepaque called Mexico''s ceramics capital?","a":"Because the craft is its living economy. With Tonalá it is one of Mexico''s two main ceramics centers, with ~2,000 artisans working clay traditions passed down since pre-Hispanic times; Calle Independencia is a pedestrian street of gallery-workshops (Talavera, blown glass, textiles), and it has been a Pueblo Mágico since October 2018.","source":"fernwayer.com / travelmexicosolo.com, 2026-07-04","si_tag":"culture"},{"q":"What should I eat and drink at El Parián?","a":"Birria, pozole, carne en su jugo and tequila. El Parián is Tlaquepaque''s iconic open-air colonial cantina — a courtyard ringed by bars with a central gazebo — where you eat Jalisco''s regional dishes over live music, ~17 minutes from the airport.","source":"travelmexicosolo.com, 2026-07-04","si_tag":"culinary"},{"q":"Is there nightlife in Tlaquepaque?","a":"Yes — El Parián runs day into evening. The colonial courtyard''s mariachi plays all day and rolls into the night over tequila and regional food, the town''s social heart. It is a Pueblo Mágico inside a metro of ~5.27M, so use rideshare or registered taxis after dark.","source":"travelmexicosolo.com / en.wikipedia.org, 2026-07-04","si_tag":"entertainment","si_fold_note":"folded from the retired `nightlife` slug into Global Live Entertainment 2026-08-23; the content is kept, the retired slug is not"}],"seo":{"meta_title":"Tlaquepaque Travel Guide 2026 — Mexico''s Ceramics Capital & El Parián | TravelWell.World","meta_description":"Plan Tlaquepaque, Jalisco: artisan ceramics on Calle Independencia, mariachi and birria at El Parián, and where to stay — with the Jalisco Level 3 advisory explained and the Guadalajara-metro carve-out.","primary_keywords":["Tlaquepaque travel","Tlaquepaque ceramics","El Parián Tlaquepaque","is Guadalajara safe 2026"],"long_tail":["Tlaquepaque pottery workshop tour","Calle Independencia artisan galleries","Tlaquepaque Pueblo Mágico guide","Guadalajara metro Level 3 advisory carve-out"],"search_language":"es-MX","local_keywords":["qué hacer en Tlaquepaque","cerámica de Tlaquepaque","El Parián Tlaquepaque mariachi","Tlaquepaque Pueblo Mágico","hoteles boutique Tlaquepaque"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"culture","status":"future"},{"si":"culinary","status":"future"}],"ultra":[{"name":"Quinta Don José Boutique Hotel (Tlaquepaque Centro)","why_ultra":"Not ultra — anchor boutique (pool/spa/gallery/restaurant); accurate tier comfort–premier","earning":"host/GDS commission on application","virtuoso_value_add":"n/a (verify; not a Virtuoso flagship)","mor":"hotel"},{"name":"Nearest true ultra = Guadalajara city luxury / Puerto Vallarta (Hotel Mousai, villas)","why_ultra":"No ultra flagship in Tlaquepaque; nearest ultra is GDL metro or PV resort, same carve-out family","earning":"on application / via host-Virtuoso","virtuoso_value_add":"verify","mor":"hotel"}],"source_verified":"2026-07-04","hero":{"query":"Tlaquepaque, Mexico"},"geo":{"lat":20.6409,"lng":-103.2938}}'::jsonb, 111),
