  ('bonaire', '11C', 'Bonaire', 'Bonaire', 'The shore-diving capital of the world', 'live', 'verified', 'oceanAerial', 'ABC Islands', '{"diveglobal","tropical","romance","ocean","adventure"}', '{"tropical"}', '{"essential","comfort","premier","luxury","ultra"}', null, 'anchor', '{"key_facts":["Shore-diving capital of the world: ~89 dive sites (97 total incl. Klein Bonaire) in Bonaire National Marine Park, most marked by yellow shore stones - drive-and-dive, self-guided, 24/7","Hilma Hooker wreck: 72m cargo ship at 30m, sunk 1984, coral-clad (snapper/barracuda/turtles) - a top Caribbean wreck dive","STINAPA $40 nature fee (all water activities, 2026) funds no-touch/no-anchor enforcement + reef restoration; covers Washington Slagbaai NP","On-island 24h recompression chamber next to Fundashon Mariadal (Kralendijk), OPERATIONAL 2026 (no longer via Curacao)","Washington Slagbaai NP (4,286 ha, 1969) + RAMSAR wetlands: flamingos, 4 sea-turtle nesting species; Lac Bay flatwater windsurf mecca","US L1; Dutch green code; south of the hurricane belt (low storm risk); USD currency; NOT a liveaboard base (shore/day-boat)"],"safety":{"emergency":"911 / 114 ambulance","hospital":"Fundashon Mariadal (Kralendijk) + adjoining 24h recompression chamber (operational 2026)","advisory_level":"L1","malaria":"none (dengue precautions)","yellow_fever":"not required unless from endemic country","hurricane":"south of the belt - low risk","activity_note":"DIVE SAFETY SPINE: 24/7 shore access - hold no-fly 18-24h (DAN), manage repetitive profiles; on-island chamber operational; buy $40 nature tag; no-touch/no-anchor; Salt Pier closed when ship berthed; booties for shore entries; strong sun","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/bonaire-st-eustatius-saba","read":"2026-08-19","page_updated":"2025-12-10T13:10:48+00:00","note":"Matched to the FCDO''s own page ''bonaire-st-eustatius-saba'' from their 226-country list; our derived slug did not resolve. Theirs is authoritative."}},"timing":{"peak":"Dec-Apr (dry, cooler ~26C water, best viz, winter-escape)","shoulder":"May-Jun + Nov (warming, calm, softer rates)","green":"Sep-Oct (warmest 28-29C, quietest, best value; south of the belt)","booking_lead":"dive-resort packages 2-5 mo (peak Dec-Apr); Klein Bonaire boat + windsurf 1-2 wk","off_season_specials":"Sep-Oct warm-water value dive weeks; shoulder windsurf (windiest May-Jul); nature/flamingo add-ons","event_peaks":"Bonaire Dive Week (~Oct, verify); Int''l Sailing Regatta (~Oct); Carnival (Feb/Mar); Dec-Apr high season","campaign_start":"Dec-Apr dive weeks by Aug (winter-escape); warm-water Sep-Oct value by Jul; windsurf by Apr; Dive Week/Regatta ~2 mo ahead"},"jewels":[{"name":"Drive-and-dive the marine park (~89 marked shore sites)","si_tag":"diveglobal","status":"live","tier":"comfort","price_band":"~$1,200-3,000/wk pp (dive+room)","timing":"year-round; Dec-Apr peak","draw_rank":1,"hook":"the signature Bonaire experience — a pickup, a yellow stone, and warm reef any hour, self-guided, on an unlimited-shore package","si":"diveglobal","blurb":"the signature Bonaire experience — a pickup, a yellow stone, and warm reef any hour, self-guided, on an unlimited-shore package","when":"year-round; Dec-Apr peak","commission":"dive-op/resort 10-20%"},{"name":"The Hilma Hooker wreck","si_tag":"diveglobal","status":"live","tier":"comfort","price_band":"within package or ~$50-90 boat","timing":"Dec-Apr","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"A 72-metre cargo ship resting at 30 m between Kralendijk and Salt Pier since 1984, now coral-clad with snapper, barracuda and turtles","si":"diveglobal","blurb":"A 72-metre cargo ship resting at 30 m between Kralendijk and Salt Pier since 1984, now coral-clad with snapper, barracuda and turtles","when":"Dec-Apr","commission":"dive-op 10-15%"},{"name":"A Klein Bonaire boat day + Salt Pier","si_tag":"diveglobal","status":"live","tier":"essential","price_band":"~$60-160/pp","timing":"year-round; Salt Pier ship-dependent","draw_rank":3,"hook":"a boat across to the uninhabited islet''s untouched reef, then the pillar-ecosystems of Salt Pier — the two best boat/tide-gated dives","si":"diveglobal","blurb":"a boat across to the uninhabited islet''s untouched reef, then the pillar-ecosystems of Salt Pier — the two best boat/tide-gated dives","when":"year-round; Salt Pier ship-dependent","commission":"dive-op + OTA"},{"name":"Klein Bonaire - the uninhabited islet","si_tag":"tropical","status":"live","tier":"essential","price_band":"~$25-60 boat","timing":"Dec-Apr","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"a boat-only islet of white sand and turtle nesting, no development — the tropical-beach counterpoint to the dive day","si":"tropical","blurb":"a boat-only islet of white sand and turtle nesting, no development — the tropical-beach counterpoint to the dive day","when":"Dec-Apr","commission":"operator/affiliate"},{"name":"A quiet dive-couple week","si_tag":"romance","status":"live","tier":"premier","price_band":"~$200-700+/night","timing":"Dec-Apr","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Bonaire is unhurried and unpretentious — shared dives, a Harbour Village or dive-resort base, sunset over the water off Kralendijk","si":"romance","blurb":"Bonaire is unhurried and unpretentious — shared dives, a Harbour Village or dive-resort base, sunset over the water off Kralendijk","when":"Dec-Apr","commission":"consortia/host"},{"name":"Lac Bay flatwater windsurfing","si_tag":"ocean","status":"future","tier":"essential","price_band":"~$40-150/pp","timing":"year-round; windiest May-Jul","draw_rank":1,"hook":"a trade-wind-fed, shallow, protected bay — the Caribbean''s flatwater windsurf mecca, beginner-friendly and world-class, in a RAMSAR wetland","si":"ocean","blurb":"a trade-wind-fed, shallow, protected bay — the Caribbean''s flatwater windsurf mecca, beginner-friendly and world-class, in a RAMSAR wetland","when":"year-round; windiest May-Jul","commission":"operator/affiliate 10-15%"},{"name":"Washington Slagbaai National Park","si_tag":"globaladv","status":"future","tier":"essential","price_band":"~$25-60 + $40 nature fee","timing":"Dec-Apr","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the rugged northwest — a 4,286-ha park, 4×4 tracks, cliffs, blowholes, salt pans and inland flamingo lakes","si":"adventure","blurb":"the rugged northwest — a 4,286-ha park, 4×4 tracks, cliffs, blowholes, salt pans and inland flamingo lakes","when":"Dec-Apr","commission":"operator/affiliate"},{"name":"Flamingos + the sea-turtle nesting shores","si_tag":"globaladv","status":"future","tier":"essential","price_band":"~$25-70/pp","timing":"year-round; turtles seasonal","draw_rank":1,"hook":"RAMSAR wetlands with resident flamingos, and beaches that nest all four Caribbean sea-turtle species — a genuine wildlife layer beside the reef","si":"adventure","blurb":"RAMSAR wetlands with resident flamingos, and beaches that nest all four Caribbean sea-turtle species — a genuine wildlife layer beside the reef","when":"year-round; turtles seasonal","commission":"operator/affiliate"}],"faq":[{"q":"What''s the real risk to plan for in Bonaire?","a":"Dive discipline, not danger. Because Bonaire is 24/7 drive-up shore diving, hold the no-fly 18-24h window and manage repetitive profiles. The on-island hyperbaric chamber next to the Kralendijk hospital is 24-hour and operational (2026).","source":"o2bonaire.com","si_tag":"safety"},{"q":"Do I have to pay the Bonaire nature fee and what does it cost?","a":"Yes - a mandatory US$40 STINAPA nature tag for all water activities (2026); it funds no-touch/no-anchor enforcement, fish surveys and reef restoration, and also covers Washington Slagbaai NP. Buy it online before you dive.","source":"bonaire.com","si_tag":"diveglobal"},{"q":"When is the best time to dive Bonaire?","a":"Year-round, but December-April is peak (cooler water, best visibility) and April-August brings the calmest seas and superb viz - Bonaire is south of the hurricane belt so there''s no real storm season.","source":"habitatbonaire.com","si_tag":"diveglobal"},{"q":"Which Bonaire dive sites should I not miss?","a":"The Hilma Hooker wreck (30m), 1000 Steps (shallow, snorkel-friendly), Salt Pier (pillar ecosystems - only when no ship is in port) and a Klein Bonaire boat day; most of the ~89 sites are self-guided drive-and-dive off the yellow stones.","source":"scubatravel.co.uk","si_tag":"diveglobal"},{"q":"Is Bonaire a liveaboard destination?","a":"No - Bonaire is the world''s shore/drive-and-dive capital (unlimited-shore packages, drive-thru tank pickup), not a liveaboard base. Book it as a resort-and-shore dive trip, not a Dive Liveaboards sailing.","source":"zubludiving.com","si_tag":"diveglobal"}],"seo":{"meta_title":"Bonaire Travel Guide: The Shore-Diving Capital, Marine Park & Nature Fee","meta_description":"Plan Bonaire - the shore-diving capital of the world: ~89 marked marine-park sites you drive up and walk into, the Hilma Hooker wreck, the $40 STINAPA nature fee, an on-island recompression chamber, flamingos and Lac Bay windsurf.","slug":"bonaire","primary_keyword":"Bonaire shore diving","long_tail":["Bonaire shore diving guide 2026","Bonaire National Marine Park dive sites","Hilma Hooker wreck dive","Bonaire STINAPA nature fee","Klein Bonaire boat dive","Lac Bay windsurfing"],"search_language":"nl","local_keywords":["Boneiru","Marine Park Boneiru","Hilma Hooker","STINAPA nature fee","Klein Bonaire","Lac Bay windsurf","Washington Slagbaai"],"hreflang":["en","nl"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-30"},"booking":{"bin":"freely_bookable","level":"L1","codes":[],"note":"Bonaire (Dutch special municipality) US L1; Dutch green code; south of the hurricane belt; USD currency"},"si_checklist_25":{"run_date":"2026-07-30","hits":6,"misses":16,"disregarded":3,"note":"Canonical 25-SI list; Dive Liveaboards is a hard MISS (shore/day-boat, NOT liveaboard); sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"diveglobal","name":"diveglobal","status":"live"},{"si":"tropical","name":"tropical","status":"live"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"live"},{"si":"ocean","name":"ocean","status":"future"},{"si":"globaladv","name":"adventure","status":"future"}],"ultra":[{"name":"Harbour Village Bonaire - beachfront luxury base","why_ultra":"the island''s upmarket resort + marina, spa + private beach, refined counterpoint to the dive-lodge norm","earning":"consortia/Virtuoso on application","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$450-1,000+/night"},{"name":"A private unlimited-shore dive week + private DM","why_ultra":"own truck + a private guide reading the reef, a Klein Bonaire charter + a Hilma Hooker deep day","earning":"dive-op/DMC","virtuoso_value_add":false,"mor":"commissionable","tier":"luxury","price_band":"on application"},{"name":"A Washington Slagbaai + flamingo private-guide 4x4 day","why_ultra":"chauffeured nature day - salt pans, blowholes, flamingo lakes, with a naturalist","earning":"DMC + venue","virtuoso_value_add":false,"mor":"commissionable","tier":"luxury","price_band":"on application"}],"source_verified":"2026-07-30","hero":{"query":"Bonaire, Bonaire"},"geo":{"lat":12.18,"lng":-68.28}}'::jsonb, 12),
